    if(s===0){a=table+book(124,126,174,36,C.teal)+rect(130,165,402,8,C.yellow,1,C.ink,2)+dim(363,230,532,230,'伸出12厘米')+badge(185,103,'成人压稳');label='成人用厚书和手，把尺子压稳';note='选无裂痕塑料尺，不用薄金属尺。';}
