 const rotor=(x,y)=>`<g data-material="folded-paper-rotor">${path(`M${x} ${y} L${x+20} ${y+2} V${y+82} L${x} ${y+82}Z`,ref('paper'),'#74826F',1.5)}${path(`M${x+12} ${y+3} V${y+77} L${x+20} ${y+82} V${y+2}Z`,'#D5D0B7','#9C9D84',1)}${path(`M${x} ${y} L${x-57} ${y-13} L${x-45} ${y-27} L${x+10} ${y-12}Z`,'#FFFCED','#74826F',1.5)}${path(`M${x+10} ${y} L${x+77} ${y+13} L${x+65} ${y+27} L${x+20} ${y+15}Z`,'#D8D1B6','#74826F',1.5)}${line(x+1,y+69,x+19,y+71,'#8A927D',1.5)}${path(`M${x+1} ${y+70} L${x+19} ${y+72} V${y+82} L${x+1} ${y+82}Z`,'#EEE5CC','#88917B',1)}</g>`;
