 const cup=c=>`<g data-material="plastic-cup">${O(c.x+c.w/2,c.y+c.h+5,c.w*.43,5,'#DDE7E4','none')}${P(`M${c.x} ${c.y}L${c.x+c.w*.1} ${c.y+c.h-4}Q${c.x+c.w/2} ${c.y+c.h+5} ${c.x+c.w*.9} ${c.y+c.h-4}L${c.x+c.w} ${c.y}`,ref('glass'),'#668D97',2)}${O(c.x+c.w/2,c.y,c.w/2,6,'none','#668D97')}${L(c.x+8,c.y+15,c.x+c.w*.1+5,c.y+c.h-17,'#fff',3)}</g>`;
