   const c=cups.find(c=>x>c.x&&x<c.x+c.w);if(c){const pad=(y-c.y)/c.h*c.w*.1;return `<g data-material="room-temperature-water">${P(`M${c.x+pad+2} ${y}H${c.x+c.w-pad-2}L${c.x+c.w*.9-2} ${c.y+c.h-5}Q${c.x+c.w/2} ${c.y+c.h+1} ${c.x+c.w*.1+2} ${c.y+c.h-5}Z`,'#CBE8F2','none',0)}${O(c.x+c.w/2,y,c.w/2-pad-2,4,'#E0F1F7','#9FCBD8')}</g>`;}
