function cabbagePilot(scene,id='cabbage'){
 if(cabbagePilotSources[scene.sceneKey]!==JSON.stringify(scene))return null;
 const E=scene.elements, safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const n=v=>Number(v), g=id+'-cabbage';
 const cups=E.filter(v=>v.type==='rect'&&['#E8EAED','#B9A7CE'].includes(v.fill));
 const skip=new Set();let art='<defs><linearGradient id="'+g+'-plastic"><stop stop-color="#eaf6f7" stop-opacity=".7"/><stop offset=".3" stop-color="#fff" stop-opacity=".1"/><stop offset=".8" stop-color="#eaf6f7" stop-opacity=".35"/><stop offset="1" stop-color="#8fb2b9" stop-opacity=".45"/></linearGradient><linearGradient id="'+g+'-metal"><stop stop-color="#edf6f8"/><stop offset=".5" stop-color="#a3bac0"/><stop offset="1" stop-color="#e2eef0"/></linearGradient></defs>';
 // Preserve white comparison backdrops before the cups.
 const backgrounds=E.filter(v=>v.type==='rect'&&v.width>500);
 for(const q of backgrounds){skip.add(q);art+='<rect x="'+q.x+'" y="'+q.y+'" width="'+q.width+'" height="'+q.height+'" rx="3" fill="white" stroke="#c7d3d3"/><path d="M'+(q.x+q.width-15)+' '+q.y+' l15 15 h-15Z" fill="#eef1ed"/>';}
 for(const q of cups){
  skip.add(q);const x=q.x-3,w=q.width+6,b=q.y+q.height+3;
  const edges=E.filter(v=>v.type==='line'&&((v.x1===x&&v.x2===x)||(v.x1===x+w&&v.x2===x+w)||(v.y1===b&&v.y2===b&&v.x1===x&&v.x2===x+w)));
  edges.forEach(v=>skip.add(v));const top=Math.min(...edges.filter(v=>v.x1===v.x2).map(v=>Math.min(v.y1,v.y2)));
  if(!Number.isFinite(top))return null;
  const foot=10,ly=q.y, inset=foot*(ly-top)/(b-top),fill=q.fill;
  art+='<ellipse cx="'+(x+w/2)+'" cy="'+(b+6)+'" rx="'+(w*.48)+'" ry="4" fill="#c9d5cd" opacity=".55"/>';
  art+='<path d="M'+x+' '+top+' L'+(x+foot)+' '+b+' Q'+(x+w/2)+' '+(b+5)+' '+(x+w-foot)+' '+b+' L'+(x+w)+' '+top+'Z" fill="url(#'+g+'-plastic)" stroke="#6d9da8" stroke-width="2"/>';
  art+='<path d="M'+(x+inset+3)+' '+ly+' H'+(x+w-inset-3)+' L'+(x+w-foot-3)+' '+(b-3)+' Q'+(x+w/2)+' '+(b+1)+' '+(x+foot+3)+' '+(b-3)+'Z" fill="'+fill+'" stroke="#b9c5c8" stroke-width="1"/>';
  art+='<ellipse cx="'+(x+w/2)+'" cy="'+ly+'" rx="'+(w/2-inset-3)+'" ry="3" fill="'+fill+'" stroke="#a4b5ba" stroke-width="1"/><ellipse cx="'+(x+w/2)+'" cy="'+top+'" rx="'+(w/2)+'" ry="7" fill="none" stroke="#6d9da8" stroke-width="1.7"/>';
  art+='<path d="M'+(x+9)+' '+(top+13)+' L'+(x+17)+' '+(b-12)+'" stroke="white" stroke-width="4" opacity=".9"/><path d="M'+(x+w-10)+' '+(top+13)+' L'+(x+w-17)+' '+(b-12)+'" stroke="#9cb9c0" stroke-width="1"/>';
  if(fill==='#E8EAED')art+='<text x="'+(x+w/2)+'" y="'+(b-17)+'" text-anchor="middle" font-size="21" fill="#64767c">?</text>';
 }
 // Dedicated measuring tools stay separate; no needle or sealed reaction container.
 const verticalArrows=E.filter(v=>v.type==='arrow'&&v.x1===v.x2);
 for(const a of verticalArrows){const x=a.x1+28,y=108;
  const hx=x+(scene.sceneKey.startsWith('cabbage-1316-')?13:38);
  art+='<g transform="translate('+hx+' 123)"><path d="M28 -2 H18 L9 -9 Q4 -12 3 -7 L10 2 L-2 0 Q-7 0 -5 5 L8 10 Q13 13 19 9 L28 9Z" fill="#e7b494" stroke="#aa7a62" stroke-width="1.2"/><path d="M12 4 L4 2 M15 8 L8 5" stroke="#ba8a71" fill="none"/><rect x="27" y="-4" width="10" height="15" fill="#93b8bf" stroke="#6d9da8"/></g>'; 
  if(scene.sceneKey.startsWith('cabbage-1316-')){
   art+='<g transform="translate('+x+' '+y+')"><rect x="0" y="5" width="12" height="29" rx="2" fill="url(#'+g+'-plastic)" stroke="#6d9da8"/><path d="M-4 5 H16 M6 -1 V5 M0 -1 H12 M4 34 V39 H8 V34" fill="none" stroke="#6d9da8" stroke-width="2"/><path d="M1 13 H6 M1 19 H6 M1 25 H6" stroke="#6d9da8"/></g>';
  }else{
   art+='<g transform="translate('+x+' '+y+') rotate(-12)"><path d="M0 0 H29 V32 H4 Z" fill="url(#'+g+'-plastic)" stroke="#6d9da8" stroke-width="1.5"/><path d="M8 10 H19 M9 18 H20 M10 26 H21 M29 6 H37 V24 H29" fill="none" stroke="#6d9da8" stroke-width="1.5"/></g>';
  }
 }
 if(scene.sceneKey==='cabbage-79-indicator')for(const q of cups){const x=q.x+q.width-19;
  art+='<path d="M'+x+' 147 L'+(x-6)+' 213" stroke="#708e98" stroke-width="5"/><path d="M'+x+' 147 L'+(x-6)+' 213" stroke="#e2eef0" stroke-width="2"/><ellipse cx="'+(x-7)+'" cy="221" rx="6" ry="10" fill="url(#'+g+'-metal)" stroke="#708e98"/>';
 }
 // Source arrows stay unchanged: quantities are labels, never inferred from liquid height.
 for(const v of E){if(skip.has(v))continue;
 if(v.type==='text')art+='<text x="'+v.x+'" y="'+Math.min(v.y,294)+'" font-size="'+(v.fontSize||20)+'" font-weight="600" fill="'+(v.fill||'#254651')+'" text-anchor="'+(v.anchor||'middle')+'">'+safe(v.text)+'</text>';
 else if(v.type==='rect'){art+='<rect x="'+v.x+'" y="'+v.y+'" width="'+v.width+'" height="'+v.height+'" rx="2" fill="'+(v.fill||'none')+'" stroke="'+(v.stroke||'#254651')+'" stroke-width="1.5"/>';}
 else if(v.type==='line'||v.type==='arrow'){art+='<line x1="'+v.x1+'" y1="'+v.y1+'" x2="'+v.x2+'" y2="'+v.y2+'" stroke="'+(v.stroke||'#254651')+'" stroke-width="'+(v.strokeWidth||2)+'" stroke-linecap="round"/>';if(v.type==='arrow'){const a=Math.atan2(v.y2-v.y1,v.x2-v.x1),l=8;art+='<path d="M'+(v.x2-l*Math.cos(a-.5))+' '+(v.y2-l*Math.sin(a-.5))+' L'+v.x2+' '+v.y2+' L'+(v.x2-l*Math.cos(a+.5))+' '+(v.y2-l*Math.sin(a+.5))+'" fill="none" stroke="'+(v.stroke||'#B87342')+'" stroke-width="2"/>';}}
 else return null;
 }
 return '<g data-illustration="cabbage-material-v1">'+art+'</g>';
}

