function seedMaterialPilot(scene,id='seed-material'){
 if(seedMaterialSources[scene.sceneKey]!==JSON.stringify(scene))return null;
 const se=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const path=(d,f='none',s='#587C79',w=1.5)=>`<path d="${d}" fill="${f}" stroke="${s}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
 const line=(x,y,x2,y2,c='#587C79',w=1)=>path(`M${x} ${y}L${x2} ${y2}`,'none',c,w);
 const text=e=>`<text x="${e.x}" y="${e.y}" font-size="${e.fontSize||20}" fill="${se(e.fill||'#193D40')}" text-anchor="${e.anchor||'start'}" font-weight="600">${se(e.text)}</text>`;
 const uid=se(id)+'-bean';
 let z=`<g data-illustration="january-seed-material-v1"><defs><radialGradient id="${uid}" cx="30%" cy="25%"><stop stop-color="#D0DC9D"/><stop offset=".48" stop-color="#9BB86C"/><stop offset="1" stop-color="#638344"/></radialGradient></defs>`;
 const els=scene.elements;
 for(const e of els){
  if(e.type==='text')continue;
  if(e.type==='rect'){
   const {x,y,width:w,height:h}=e;
   if(e.fill==='none'){
    // Open shallow transparent plastic box, seen from above; rim, not a lid.
    z+=`<rect x="${x}" y="${y+2}" width="${w}" height="${h}" rx="9" fill="#D9E3DA" opacity=".35"/>`;
    z+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#F4FAF5" fill-opacity=".55" stroke="#75989A" stroke-width="2"/>`;
    z+=path(`M${x+6} ${y+h-8} Q${x+7} ${y+h-3} ${x+14} ${y+h-3} H${x+w-13}`,'none','#AEC5C3',2);
   }else if(w>30){
    const wet=e.fill==='#D9ECE8';
    // Absorbent paper texture stays light, never a blue pool or water surface.
    z+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${wet?'#E3EEE6':'#FFFCF1'}" stroke="#A9B8AA" stroke-width=".9"/>`;
    z+=path(`M${x+2} ${y+h-4} H${x+w-4} V${y+3}`,'none',wet?'#BACFC0':'#DED9C6',1.1);
    for(let a=x+12;a<x+w-4;a+=15)for(let b=y+11;b<y+h-4;b+=14)z+=path(`M${a-1.4} ${b}h2.8 M${a} ${b-1.4}v2.8`,'none',wet?'#C3D7C9':'#E9E3D4',.65);
   }else{
    // Needle-free graduated plastic pipette and squeeze bulb.
    z+=path(`M${x+w*.27} ${y+6}Q${x-3} ${y-2} ${x+w/2} ${y-5}Q${x+w+3} ${y-2} ${x+w*.73} ${y+6}V${y+h-8}L${x+w/2+2} ${y+h}H${x+w/2-2}L${x+w*.27} ${y+h-8}Z`,'#DDEFF0','#6B929B',1.3);
    // Adult fingers squeeze the bulb; pipette stays above the paper edge.
    z+=`<g transform="translate(${x+w/2+1} ${y+1}) scale(.62)">`+path('M0 0Q5-6 10-4L28 2L39 1V15L24 16L8 10Q2 11 0 7L11 7L4 4Z','#EBC5A7','#B2876A',1.1)+`<rect x="37" y="0" width="12" height="16" fill="#9FC2C8" stroke="#6F939B" stroke-width="1"/></g>`;
    for(let t=10;t<h-8;t+=7)z+=line(x+w*.28,y+t,x+w*.52,y+t,'#789BA1',.8);
    z+=path(`M${x+w/2} ${y+h+2}q-3 5 0 6q3-1 0-6`,'#ABD6DE','#789BA1',.6);
   }
  }else if(e.type==='circle'){
   const r=e.r*1.27;
   z+=`<ellipse cx="${e.x+1}" cy="${e.y+2}" rx="${r}" ry="${r*.7}" fill="#708569" opacity=".15"/>`;
   z+=`<g transform="translate(${e.x} ${e.y}) rotate(-22)">`;
   z+=path(`M${-r} 0C${-r} ${-r*.95} ${r*.65} ${-r} ${r} ${-r*.1}C${r*1.1} ${r*.75} ${-r*.6} ${r} ${-r} 0Z`,`url(#${uid})`,'#58733F',.7);
   z+=`<ellipse cx="${r*.18}" cy="${r*.1}" rx="${r*.17}" ry="${r*.45}" fill="#E8E6BC" stroke="#75904D" stroke-width=".5"/>`;
   z+='</g>';
  }else if(e.type==='line'||e.type==='arrow'){
   z+=line(e.x1,e.y1,e.x2,e.y2,e.stroke||'#587C79',e.strokeWidth||2);
   if(e.type==='arrow'){const a=Math.atan2(e.y2-e.y1,e.x2-e.x1),r=7;z+=path(`M${e.x2-r*Math.cos(a-.5)} ${e.y2-r*Math.sin(a-.5)}L${e.x2} ${e.y2}L${e.x2-r*Math.cos(a+.5)} ${e.y2-r*Math.sin(a+.5)}`,'none',e.stroke||'#BF7C45',2);}
  }
 }
 z+=els.filter(e=>e.type==='text').map(text).join('');
 return z+'</g>';
}

function renderProtocolDiagram(e,s,ageBand,protocol){
 if(!Array.isArray(protocol.diagrams)||protocol.diagrams.length!==4)throw new TypeError('Protocol requires four diagrams');
 const artwork=protocol.diagrams.map(validateProtocolScene),scene=protocol.diagrams[s],id=`science-diagram-${e.id}-${s}-${++diagramSerial}`,label=protocol.steps?.[s]?.title||e.steps?.[s]?.title||`第${s+1}步`;
 return `<svg xmlns="http://www.w3.org/2000/svg" class="science-diagram" viewBox="0 0 640 360" width="640" height="360" role="img" aria-labelledby="${id}-title ${id}-desc" style="display:block;max-width:100%;height:auto;font-family:system-ui,-apple-system,'Noto Sans CJK SC','Microsoft YaHei',sans-serif"><title id="${id}-title">第${esc(e.day??e.id)}天，第${s+1}步：${esc(e.title)} · ${esc(ageBand)}岁</title><desc id="${id}-desc">${esc(scene.description)}</desc>${rect(0,0,640,360,C.cream,0,'none',0)}${wrappedText(e.title+' · 分龄操作图',25,35,25,21,C.ink,'start',1)}${txt(610,36,`${s+1} / 4`,22,C.teal,'end')}${line(24,58,616,58,'#DDE5D9',1.5)}<defs><clipPath id="${id}-scene"><rect x="24" y="65" width="592" height="235"/></clipPath></defs><g clip-path="url(#${id}-scene)">${(e.id===1?bridgeMaterialPilot(scene,id):e.id===5?cabbagePilot(scene,id):e.id===6?seedMaterialPilot(scene,id):e.id===3?leafPilot(scene,id):[2,4].includes(e.id)&&ageBand==='4-6'?januaryActionPilot(scene,id):e.id===2?sugarOlderPilot(scene,id):e.id===4?renderRotorOlderPilot(scene,id):null)??artwork[s]}</g>${rect(0,307,640,53,'#E9EFE4',0,'none',0)}${wrappedText(label,320,338,29,21,C.ink,'middle',1)}</svg>`;
}
export function renderActivityDiagram(activity,stepIndex=0,ageBand='7-9'){
 const e=activity,s=Math.min(3,Math.max(0,Math.floor(Number(stepIndex)||0)));
 const protocol=e.activeAgeProtocol||e.ageProtocols?.[ageBand];
 if(protocol)return renderProtocolDiagram(e,s,ageBand,protocol);
 if(e.id<=30)return renderDiagram(e.id,s,ageBand);
 const young=ageBand==='4-6',scene=annualScene(e,s,ageBand),id=`science-diagram-${e.id}-${s}-${++diagramSerial}`;
 return `<svg xmlns="http://www.w3.org/2000/svg" class="science-diagram" viewBox="0 0 640 360" width="640" height="360" role="img" aria-labelledby="${id}-title ${id}-desc" style="display:block;max-width:100%;height:auto;font-family:system-ui,-apple-system,'Noto Sans CJK SC','Microsoft YaHei',sans-serif"><title id="${id}-title">第${e.day}天，第${s+1}步：${esc(e.title)}</title><desc id="${id}-desc">${esc(e.steps[s].detail)} ${esc(scene.note)} ${esc(e.ageGuides[ageBand].steps[s].caption)}</desc>${rect(0,0,640,360,C.cream,0,'none',0)}${wrappedText(e.title+' · 操作关系图',25,35,25,21,C.ink,'start',1)}${txt(610,36,`${s+1} / 4`,22,C.teal,'end')}${line(24,58,616,58,'#DDE5D9',1.5)}${scene.art}${rect(0,307,640,53,'#E9EFE4',0,'none',0)}${wrappedText(scene.label,320,338,29,21,C.ink,'middle',1)}</svg>`;
}
